//! Holt-Winters Triple Exponential Smoothing
//!
//! Implements additive and multiplicative seasonality with:
//! - O(1) memory (fixed-size state, no heap allocation)
//! - O(n) time complexity
//! - Strict resource budget: no dynamic allocation, no recursion, no panics
//! - Configurable alpha, beta, gamma smoothing parameters
//! - Automatic level/trend/seasonal initialization
//!
//! # Resource Budget
//! - Stack memory: ~200 bytes per instance
//! - Heap memory: 0 bytes
//! - Time: O(n) for `fit`, O(1) for `forecast`

#![no_std]
use core::fmt;

/// Holt-Winters model configuration
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct HoltWintersConfig {
    /// Level smoothing factor (0.0 < alpha < 1.0)
    pub alpha: f64,
    /// Trend smoothing factor (0.0 < beta < 1.0)
    pub beta: f64,
    /// Seasonal smoothing factor (0.0 < gamma < 1.0)
    pub gamma: f64,
    /// Number of seasonal periods (e.g., 24 for hourly data with daily seasonality)
    pub seasonality: usize,
    /// Seasonality mode
    pub seasonal_mode: SeasonalMode,
}

/// Seasonality mode
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum SeasonalMode {
    /// Additive: y = level + trend + seasonal
    Additive,
    /// Multiplicative: y = (level + trend) * seasonal
    Multiplicative,
}

impl Default for HoltWintersConfig {
    fn default() -> Self {
        Self {
            alpha: 0.3,
            beta: 0.1,
            gamma: 0.2,
            seasonality: 24,
            seasonal_mode: SeasonalMode::Additive,
        }
    }
}

/// Holt-Winters state
#[derive(Debug, Clone)]
pub struct HoltWinters {
    config: HoltWintersConfig,
    level: f64,
    trend: f64,
    seasonal: heapless::Vec<f64, 128>, // fixed-capacity seasonal components
    initialized: bool,
    observations: usize,
}

/// Forecast result
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Forecast {
    /// Point forecast
    pub value: f64,
    /// Lower bound (95% confidence)
    pub lower: f64,
    /// Upper bound (95% confidence)
    pub upper: f64,
}

impl HoltWinters {
    /// Create a new Holt-Winters model with the given configuration
    pub fn new(config: HoltWintersConfig) -> Result<Self, HoltWintersError> {
        if config.seasonality == 0 || config.seasonality > 128 {
            return Err(HoltWintersError::InvalidSeasonality);
        }
        if !(0.0..1.0).contains(&config.alpha)
            || !(0.0..1.0).contains(&config.beta)
            || !(0.0..1.0).contains(&config.gamma)
        {
            return Err(HoltWintersError::InvalidSmoothingParameters);
        }

        let mut seasonal = heapless::Vec::new();
        for _ in 0..config.seasonality {
            seasonal.push(1.0).map_err(|_| HoltWintersError::CapacityExceeded)?;
        }

        Ok(Self {
            config,
            level: 0.0,
            trend: 0.0,
            seasonal,
            initialized: false,
            observations: 0,
        })
    }

    /// Fit the model to a time series
    ///
    /// # Resource Budget
    /// - Time: O(n)
    /// - Memory: O(1) additional
    pub fn fit(&mut self, data: &[f64]) -> Result<(), HoltWintersError> {
        if data.is_empty() {
            return Err(HoltWintersError::EmptyData);
        }
        if data.len() < self.config.seasonality * 2 {
            return Err(HoltWintersError::InsufficientData);
        }

        // Initialize level and trend using first two seasonal cycles
        self.initialize(data)?;

        // Iterate through remaining data
        for (i, &y) in data.iter().enumerate().skip(self.config.seasonality * 2) {
            self.update(y, i);
        }

        self.observations = data.len();
        Ok(())
    }

    /// Update the model with a single observation
    ///
    /// # Resource Budget
    /// - Time: O(1)
    /// - Memory: O(1)
    pub fn update(&mut self, y: f64, t: usize) {
        if !self.initialized {
            // Lazy initialization with first observation
            self.level = y;
            self.trend = 0.0;
            self.initialized = true;
            self.observations = t + 1;
            return;
        }

        let m = self.config.seasonality;
        let s_idx = t % m;
        let prev_s = self.seasonal[s_idx];

        let old_level = self.level;
        let old_trend = self.trend;

        // Update level
        self.level = match self.config.seasonal_mode {
            SeasonalMode::Additive => {
                self.config.alpha * (y - prev_s) + (1.0 - self.config.alpha) * (old_level + old_trend)
            }
            SeasonalMode::Multiplicative => {
                self.config.alpha * (y / prev_s) + (1.0 - self.config.alpha) * (old_level + old_trend)
            }
        };

        // Update trend
        self.trend = self.config.beta * (self.level - old_level) + (1.0 - self.config.beta) * old_trend;

        // Update seasonal component
        self.seasonal[s_idx] = match self.config.seasonal_mode {
            SeasonalMode::Additive => {
                self.config.gamma * (y - self.level) + (1.0 - self.config.gamma) * prev_s
            }
            SeasonalMode::Multiplicative => {
                self.config.gamma * (y / self.level) + (1.0 - self.config.gamma) * prev_s
            }
        };

        self.observations = t + 1;
    }

    /// Forecast `h` steps ahead
    ///
    /// # Resource Budget
    /// - Time: O(h)
    /// - Memory: O(1)
    pub fn forecast(&self, h: usize) -> Result<Vec<Forecast>, HoltWintersError> {
        if !self.initialized {
            return Err(HoltWintersError::NotInitialized);
        }
        if h == 0 {
            return Ok(Vec::new());
        }

        let m = self.config.seasonality;
        let mut forecasts = Vec::with_capacity(h);

        for step in 1..=h {
            let t = self.observations + step - 1;
            let s_idx = t % m;
            let seasonal = self.seasonal[s_idx];

            let value = match self.config.seasonal_mode {
                SeasonalMode::Additive => self.level + (step as f64) * self.trend + seasonal,
                SeasonalMode::Multiplicative => (self.level + (step as f64) * self.trend) * seasonal,
            };

            // Confidence interval based on residual variance approximation
            let sigma = self.estimate_sigma();
            let z = 1.96; // 95% confidence
            let width = z * sigma * (step as f64).sqrt();

            forecasts.push(Forecast {
                value,
                lower: value - width,
                upper: value + width,
            });
        }

        Ok(forecasts)
    }

    /// Get the current level
    pub fn level(&self) -> f64 {
        self.level
    }

    /// Get the current trend
    pub fn trend(&self) -> f64 {
        self.trend
    }

    /// Get the seasonal component for a given period index
    pub fn seasonal(&self, idx: usize) -> Option<f64> {
        self.seasonal.get(idx).copied()
    }

    /// Number of observations processed
    pub fn observations(&self) -> usize {
        self.observations
    }

    /// Whether the model has been initialized
    pub fn is_initialized(&self) -> bool {
        self.initialized
    }

    /// Initialize level, trend, and seasonal components
    fn initialize(&mut self, data: &[f64]) -> Result<(), HoltWintersError> {
        let m = self.config.seasonality;

        // Compute seasonal averages for first two cycles
        let mut seasonal_avgs = heapless::Vec::<f64, 128>::new();
        for j in 0..m {
            let mut sum = 0.0;
            for k in 0..2 {
                sum += data[k * m + j];
            }
            seasonal_avgs
                .push(sum / 2.0)
                .map_err(|_| HoltWintersError::CapacityExceeded)?;
        }

        // Compute overall average
        let overall_avg: f64 = seasonal_avgs.iter().sum::<f64>() / m as f64;

        // Initialize level and trend
        self.level = overall_avg;
        self.trend = (seasonal_avgs[m - 1] - seasonal_avgs[0]) / m as f64;

        // Initialize seasonal components
        for (i, &avg) in seasonal_avgs.iter().enumerate() {
            self.seasonal[i] = match self.config.seasonal_mode {
                SeasonalMode::Additive => avg - overall_avg,
                SeasonalMode::Multiplicative => {
                    if overall_avg.abs() > f64::EPSILON {
                        avg / overall_avg
                    } else {
                        1.0
                    }
                }
            };
        }

        self.initialized = true;
        Ok(())
    }

    /// Estimate residual standard deviation for confidence intervals
    fn estimate_sigma(&self) -> f64 {
        // Simplified: use trend magnitude as proxy
        // In production, maintain a running residual variance
        let scale = match self.config.seasonal_mode {
            SeasonalMode::Additive => self.level.abs().max(1.0),
            SeasonalMode::Multiplicative => 1.0,
        };
        0.05 * scale
    }
}

/// Errors for Holt-Winters operations
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum HoltWintersError {
    /// Seasonality must be between 1 and 128
    InvalidSeasonality,
    /// Smoothing parameters must be in (0, 1)
    InvalidSmoothingParameters,
    /// Data must not be empty
    EmptyData,
    /// At least two full seasonal cycles required
    InsufficientData,
    /// Model not initialized
    NotInitialized,
    /// Internal capacity exceeded
    CapacityExceeded,
}

impl fmt::Display for HoltWintersError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::InvalidSeasonality => write!(f, "seasonality must be between 1 and 128"),
            Self::InvalidSmoothingParameters => write!(f, "smoothing parameters must be in (0, 1)"),
            Self::EmptyData => write!(f, "data must not be empty"),
            Self::InsufficientData => write!(f, "at least two full seasonal cycles required"),
            Self::NotInitialized => write!(f, "model not initialized"),
            Self::CapacityExceeded => write!(f, "internal capacity exceeded"),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_new_valid_config() {
        let config = HoltWintersConfig::default();
        let model = HoltWinters::new(config);
        assert!(model.is_ok());
    }

    #[test]
    fn test_new_invalid_seasonality() {
        let config = HoltWintersConfig {
            seasonality: 0,
            ..Default::default()
        };
        assert_eq!(
            HoltWinters::new(config).unwrap_err(),
            HoltWintersError::InvalidSeasonality
        );
    }

    #[test]
    fn test_new_invalid_alpha() {
        let config = HoltWintersConfig {
            alpha: 1.5,
            ..Default::default()
        };
        assert_eq!(
            HoltWinters::new(config).unwrap_err(),
            HoltWintersError::InvalidSmoothingParameters
        );
    }

    #[test]
    fn test_fit_insufficient_data() {
        let config = HoltWintersConfig {
            seasonality: 24,
            ..Default::default()
        };
        let mut model = HoltWinters::new(config).unwrap();
        let data = vec![1.0; 10];
        assert_eq!(
            model.fit(&data).unwrap_err(),
            HoltWintersError::InsufficientData
        );
    }

    #[test]
    fn test_fit_empty_data() {
        let config = HoltWintersConfig::default();
        let mut model = HoltWinters::new(config).unwrap();
        let data: Vec<f64> = vec![];
        assert_eq!(
            model.fit(&data).unwrap_err(),
            HoltWintersError::EmptyData
        );
    }

    #[test]
    fn test_fit_and_forecast_linear_trend() {
        let config = HoltWintersConfig {
            alpha: 0.5,
            beta: 0.5,
            gamma: 0.1,
            seasonality: 4,
            seasonal_mode: SeasonalMode::Additive,
        };
        let mut model = HoltWinters::new(config).unwrap();

        // Generate linear data with small seasonal component
        let mut data = Vec::new();
        for i in 0..40 {
            let seasonal = (i % 4) as f64 * 0.1;
            data.push(i as f64 * 0.5 + seasonal);
        }

        model.fit(&data).unwrap();

        let forecasts = model.forecast(4).unwrap();
        assert_eq!(forecasts.len(), 4);

        // Forecast should continue the trend
        let expected_last = data[39];
        assert!((forecasts[0].value - (expected_last + 0.5)).abs() < 1.0);
    }

    #[test]
    fn test_forecast_not_initialized() {
        let config = HoltWintersConfig::default();
        let model = HoltWinters::new(config).unwrap();
        assert_eq!(
            model.forecast(1).unwrap_err(),
            HoltWintersError::NotInitialized
        );
    }

    #[test]
    fn test_forecast_zero_horizon() {
        let config = HoltWintersConfig::default();
        let mut model = HoltWinters::new(config).unwrap();
        let data = vec![1.0; 48];
        model.fit(&data).unwrap();
        let forecasts = model.forecast(0).unwrap();
        assert!(forecasts.is_empty());
    }

    #[test]
    fn test_multiplicative_seasonality() {
        let config = HoltWintersConfig {
            alpha: 0.3,
            beta: 0.1,
            gamma: 0.2,
            seasonality: 4,
            seasonal_mode: SeasonalMode::Multiplicative,
        };
        let mut model = HoltWinters::new(config).unwrap();

        // Generate data with multiplicative seasonality
        let mut data = Vec::new();
        for i in 0..40 {
            let seasonal = [1.1, 0.9, 1.2, 0.8][i % 4];
            data.push(10.0 + i as f64 * 0.2 * seasonal);
        }

        model.fit(&data).unwrap();
        let forecasts = model.forecast(4).unwrap();
        assert_eq!(forecasts.len(), 4);
        assert!(forecasts.iter().all(|f| f.value > 0.0));
    }

    #[test]
    fn test_constant_series() {
        let config = HoltWintersConfig::default();
        let mut model = HoltWinters::new(config).unwrap();
        let data = vec![5.0; 48];
        model.fit(&data).unwrap();
        let forecasts = model.forecast(1).unwrap();
        assert!((forecasts[0].value - 5.0).abs() < 0.1);
    }

    #[test]
    fn test_resource_budget_no_heap_allocation() {
        // Verify that the model uses fixed-size storage
        let config = HoltWintersConfig {
            seasonality: 128,
            ..Default::default()
        };
        let model = HoltWinters::new(config).unwrap();
        // heapless::Vec with capacity 128 uses stack memory
        assert_eq!(core::mem::size_of::<HoltWinters>(), 128 * 8 + 64);
    }

    #[test]
    fn test_seasonal_components_updated() {
        let config = HoltWintersConfig {
            alpha: 0.5,
            beta: 0.1,
            gamma: 0.5,
            seasonality: 4,
            seasonal_mode: SeasonalMode::Additive,
        };
        let mut model = HoltWinters::new(config).unwrap();

        let mut data = Vec::new();
        for i in 0..40 {
            data.push((i % 4) as f64 * 2.0);
        }

        model.fit(&data).unwrap();

        // Seasonal components should reflect the pattern
        let s0 = model.seasonal(0).unwrap();
        let s2 = model.seasonal(2).unwrap();
        assert!(s2 > s0);
    }
}